package soroauth

import (
	"bytes"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"

	"github.com/stellar/go-stellar-sdk/xdr"
)

// Cross-version compatibility: entries signed by an earlier release must keep
// verifying, inspecting and re-encoding the same way under the current code.
//
// The golden vectors cannot catch a wire-format regression: they are
// regenerated by every `make vectors`, so they move with the code. The frozen
// set is the opposite: it is signed by v0.1.0, committed under
// testdata/frozen/v0.1.0/, and never regenerated. If reading a stored,
// pre-signed entry changes, these tests fail instead of the change landing
// unnoticed.
//
// The set is produced by scripts/frozengen run against the release tag; see
// testdata/frozen/README.md for the process and for why the directory is
// deliberately outside testdata/vectors.

// frozenEntryFile is the committed shape of one frozen release entry. It
// mirrors the golden vectors where the fields overlap, plus the release's own
// Inspect output.
type frozenEntryFile struct {
	Name              string          `json:"name"`
	SourceRelease     string          `json:"source_release"`
	NetworkPassphrase string          `json:"network_passphrase"`
	ValidUntilLedger  uint32          `json:"valid_until_ledger"`
	SignedEntryXDR    string          `json:"signed_entry_xdr"`
	PreimageXDR       string          `json:"preimage_xdr"`
	PayloadHex        string          `json:"payload_hex"`
	Inspect           json.RawMessage `json:"inspect"`
}

// frozenInspect is the projection of Inspect that both v0.1.0 and the current
// build emit: the fields that existed at v0.1.0. The current NodeInfo carries
// an extra `shape` field, so comparing JSON text would fail on a legitimate
// addition; decoding into this struct drops the new field and compares only
// what the release could have produced.
type frozenInspect struct {
	CredentialType   string       `json:"credential_type"`
	AddressBound     bool         `json:"address_bound"`
	Address          string       `json:"address,omitempty"`
	Nonce            int64        `json:"nonce,omitempty"`
	ValidUntilLedger uint32       `json:"valid_until_ledger,omitempty"`
	TopLevelSigned   bool         `json:"top_level_signed"`
	Delegates        []frozenNode `json:"delegates,omitempty"`
	RootContract     string       `json:"root_contract,omitempty"`
	RootFunction     string       `json:"root_function,omitempty"`
	SubInvocations   int          `json:"sub_invocations"`
}

type frozenNode struct {
	Address string       `json:"address"`
	Signed  bool         `json:"signed"`
	Nested  []frozenNode `json:"nested,omitempty"`
}

// frozenRelease is the release whose entries are committed. A second release
// gets its own directory and its own version of this constant's use; the test
// fails if a file's source_release does not match the directory it sits in.
const frozenRelease = "v0.1.0"

func loadFrozenEntries(t *testing.T) []frozenEntryFile {
	t.Helper()
	dir := filepath.Join("testdata", "frozen", frozenRelease)
	names, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("reading %s: %v", dir, err)
	}
	var out []frozenEntryFile
	for _, e := range names {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		raw, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			t.Fatalf("reading %s: %v", e.Name(), err)
		}
		var fe frozenEntryFile
		if err := json.Unmarshal(raw, &fe); err != nil {
			t.Fatalf("parsing %s: %v", e.Name(), err)
		}
		out = append(out, fe)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// TestFrozenReleaseEntries is the cross-version guarantee: every entry signed
// by the release still decodes to the same bytes, still produces the payload
// the release recorded, still verifies, and still inspects to the release's
// committed structure.
func TestFrozenReleaseEntries(t *testing.T) {
	entries := loadFrozenEntries(t)
	if len(entries) == 0 {
		t.Fatalf("no frozen entries under testdata/frozen/%s", frozenRelease)
	}

	for _, fe := range entries {
		t.Run(fe.Name, func(t *testing.T) {
			if fe.SourceRelease != frozenRelease {
				t.Fatalf("source_release = %q, want %q (a file must name the release it was signed by)", fe.SourceRelease, frozenRelease)
			}

			entry, err := DecodeAuthorizationEntry(fe.SignedEntryXDR)
			if err != nil {
				t.Fatalf("the current decoder refused a %s entry: %v", frozenRelease, err)
			}

			// Re-encoding must be byte-identical: the wire format did not move.
			reencoded, err := entry.MarshalBinary()
			if err != nil {
				t.Fatalf("re-encoding: %v", err)
			}
			if got := base64.StdEncoding.EncodeToString(reencoded); got != fe.SignedEntryXDR {
				t.Fatalf("re-encoding changed the entry bytes")
			}

			// The payload the release recorded is the payload the current code
			// rebuilds from the entry alone.
			preimage, err := Preimage(entry, fe.ValidUntilLedger, fe.NetworkPassphrase)
			if err != nil {
				t.Fatalf("Preimage: %v", err)
			}
			rawPreimage, err := preimage.MarshalBinary()
			if err != nil {
				t.Fatalf("marshalling preimage: %v", err)
			}
			if got := base64.StdEncoding.EncodeToString(rawPreimage); got != fe.PreimageXDR {
				t.Errorf("preimage changed:\n got %s\nwant %s", got, fe.PreimageXDR)
			}
			payload, err := Payload(preimage)
			if err != nil {
				t.Fatalf("Payload: %v", err)
			}
			if got := hex.EncodeToString(payload[:]); got != fe.PayloadHex {
				t.Errorf("payload changed:\n got %s\nwant %s", got, fe.PayloadHex)
			}

			// A pre-signed entry from the release still verifies.
			report, err := VerifyEntry(entry, fe.NetworkPassphrase)
			if err != nil {
				t.Fatalf("VerifyEntry: %v", err)
			}
			if !report.Verified() {
				t.Errorf("a %s entry no longer verifies: %+v", frozenRelease, report)
			}

			// And it inspects to the structure the release recorded.
			info, err := Inspect(entry)
			if err != nil {
				t.Fatalf("Inspect: %v", err)
			}
			infoJSON, err := json.Marshal(info)
			if err != nil {
				t.Fatalf("marshalling inspect: %v", err)
			}
			var got, want frozenInspect
			if err := json.Unmarshal(infoJSON, &got); err != nil {
				t.Fatalf("parsing current inspect: %v", err)
			}
			if err := json.Unmarshal(fe.Inspect, &want); err != nil {
				t.Fatalf("parsing recorded inspect: %v", err)
			}
			if !reflect.DeepEqual(got, want) {
				t.Errorf("inspect changed:\n got %+v\nwant %+v", got, want)
			}
		})
	}
}

// TestFrozenReleaseEntriesDiff checks that DiffEntries can read a release entry
// and reports it against itself as identical, and that two frozen entries on
// different arms differ in the way the payload model says they must.
func TestFrozenReleaseEntriesDiff(t *testing.T) {
	entries := loadFrozenEntries(t)
	byName := make(map[string]xdr.SorobanAuthorizationEntry, len(entries))
	for _, fe := range entries {
		entry, err := DecodeAuthorizationEntry(fe.SignedEntryXDR)
		if err != nil {
			t.Fatalf("decoding %s: %v", fe.Name, err)
		}
		byName[fe.Name] = entry
	}

	for name, entry := range byName {
		diff, err := DiffEntries(entry, entry)
		if err != nil {
			t.Fatalf("diffing %s against itself: %v", name, err)
		}
		if !diff.Identical {
			t.Errorf("diffing %s against itself is not identical: %s", name, diff.Summary)
		}
	}

	legacy, ok := byName["v0_1_0_address"]
	if !ok {
		t.Fatal("v0_1_0_address is missing from the frozen set")
	}
	v2, ok := byName["v0_1_0_address_v2"]
	if !ok {
		t.Fatal("v0_1_0_address_v2 is missing from the frozen set")
	}
	diff, err := DiffEntries(legacy, v2)
	if err != nil {
		t.Fatalf("diffing across arms: %v", err)
	}
	if diff.Identical || !diff.PayloadChanged {
		t.Errorf("a legacy and a V2 entry must differ and move the payload, got identical=%v payloadChanged=%v",
			diff.Identical, diff.PayloadChanged)
	}
}

// TestFrozenSetIsSeparateFromVectors enforces the whole point of the set: it
// must not live under testdata/vectors, which `make vectors` rewrites, and it
// must not be produced by the vector generator. A frozen entry that moved with
// the generator would prove nothing about the release.
func TestFrozenSetIsSeparateFromVectors(t *testing.T) {
	dir := filepath.Join("testdata", "frozen", frozenRelease)
	vectorsDir := filepath.Join("testdata", "vectors")

	absFrozen, err := filepath.Abs(dir)
	if err != nil {
		t.Fatal(err)
	}
	absVectors, err := filepath.Abs(vectorsDir)
	if err != nil {
		t.Fatal(err)
	}
	if strings.HasPrefix(absFrozen+string(filepath.Separator), absVectors+string(filepath.Separator)) {
		t.Fatalf("the frozen set lives under %s, which make vectors rewrites", vectorsDir)
	}

	// A marker the vector generator does not write: the README, which documents
	// that the set is hand-committed per release. If a future generator cleared
	// the directory, this would go with it and the test would fail.
	readme, err := os.ReadFile(filepath.Join("testdata", "frozen", "README.md"))
	if err != nil {
		t.Fatalf("reading the frozen-set README: %v", err)
	}
	if !bytes.Contains(readme, []byte("never regenerated")) {
		t.Error("testdata/frozen/README.md must state that the frozen set is never regenerated")
	}
}
